import {formatDate} from './dates.js';
import {parseAmount} from './search.js';
export function initMarket({state,storage,$,esc,fa,modal,toast,shops,openProduct}){
 const list=k=>{const v=storage.get(k,[]);return Array.isArray(v)?v:[]};
 const statuses={open:'ثبت‌شده',reviewing:'در حال بررسی',resolved:'رسیدگی‌شده',rejected:'ردشده'};
 async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok)throw Error(r.status===429?'کمی صبر کن و دوباره تلاش کن.':'دریافت اطلاعات ممکن نشد.');return r.json()}
 const workspace=$('.workspace-actions');workspace.insertAdjacentHTML('beforeend','<button id="priceWatches">پیگیری قیمت</button><button id="myReports">گزارش‌های من</button><button id="shopsDirectory">فروشگاه‌ها</button><button id="smartAdvisor">راهنمای خرید</button>');
 $('#smartAdvisor').onclick=()=>$('#askAdvisor').click();
 $('#myReports').onclick=async()=>{const reports=list('ty:reports');modal('<h2>گزارش‌های من</h2><p>رسیدها روی همین مرورگر ذخیره می‌شوند. پاک کردن اطلاعات مرورگر، دسترسی به پیگیری را حذف می‌کند.</p><div id="reportReceipts">در حال دریافت…</div>');const box=$('#reportReceipts');if(!reports.length){box.textContent='هنوز گزارشی ثبت نکرده‌ای.';return}const results=await Promise.all(reports.slice(-10).reverse().map(async r=>{try{const d=await api('reports/'+r.id+'?receipt='+encodeURIComponent(r.receipt));return `<article class="market-record"><strong>${esc(r.title)}</strong><p>${esc(statuses[d.status])} · ${esc(formatDate(d.at,true))}</p><p>${esc(d.reply||'هنوز پاسخی ثبت نشده است.')}</p></article>`}catch(e){return `<p>${esc(r.title)}: ${esc(e.message)}</p>`}}));box.innerHTML=results.join('')};
 $('#priceWatches').onclick=()=>{const watches=list('ty:watches');modal('<h2>قیمت‌های تحت پیگیری</h2><p>هدف قیمت روی همین دستگاه ذخیره می‌شود. هنگام باز کردن محصول، با قیمت ثبت‌شده مقایسه می‌شود؛ پیامک یا پایش زنده فعال نیست.</p>'+ (watches.length?watches.map(w=>`<article class="market-record"><button data-watch-open="${esc(w.id)}">${esc(w.title)}</button><p>هدف: ${fa(w.target)} تومان · ${esc(formatDate(w.at))}</p><button data-watch-remove="${esc(w.id)}">حذف پیگیری</button></article>`).join(''):'<p>از صفحهٔ محصول، قیمت دلخواهت را مشخص کن.</p>'))};
 $('#shopsDirectory').onclick=()=>{modal('<h2>فروشگاه‌ها</h2><p>نام‌ها و اطلاعات از مجموعه‌داده هستند؛ تماس و موجودی زنده تأیید نشده است.</p><input id="shopLookup" placeholder="نام فروشگاه یا آدرس" aria-label="جستجوی فروشگاه"><label><input id="onlySavedShops" type="checkbox"> فقط فروشگاه‌های ذخیره‌شده</label><div id="directoryList"></div>');const render=()=>{const saved=list('ty:shops'),q=$('#shopLookup').value.trim();const rows=Object.entries(shops).filter(([id,s])=>(!$('#onlySavedShops').checked||saved.includes(id))&&(!q||(s.name+' '+s.address).includes(q))).slice(0,40);$('#directoryList').innerHTML=rows.map(([id,s])=>`<article class="market-record"><strong>${esc(s.name)}</strong><p>${esc(s.address||s.location_label||'آدرس نامشخص')}</p><button data-favorite-shop="${esc(id)}" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'حذف از ذخیره‌ها':'ذخیرهٔ فروشگاه'}</button></article>`).join('')||'<p>فروشگاهی پیدا نشد.</p>'};$('#shopLookup').oninput=render;$('#onlySavedShops').onchange=render;$('#directoryList').onclick=e=>{const b=e.target.closest('[data-favorite-shop]');if(!b)return;const saved=list('ty:shops'),id=b.dataset.favoriteShop;storage.set('ty:shops',saved.includes(id)?saved.filter(x=>x!==id):[...saved,id].slice(-100));render()};render()};
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.watchOpen){$('#modal').close();openProduct(b.dataset.watchOpen)}if(b?.dataset.watchRemove){storage.set('ty:watches',list('ty:watches').filter(x=>x.id!==b.dataset.watchRemove));$('#priceWatches').click()}});
 async function history(p){modal('<h2>قیمت و سابقهٔ تغییرات</h2><div id="publicHistory">در حال دریافت…</div>');const box=$('#publicHistory');try{const d=await api('history/'+encodeURIComponent(p.id));const points=d.changes.filter(x=>x.price>0&&x.previous>0);let chart='';if(points.length){const values=[points[0].previous,...points.map(x=>x.price)],min=Math.min(...values),max=Math.max(...values),xy=values.map((v,i)=>`${30+i*540/(values.length-1)},${150-(v-min)/(max-min||1)*120}`).join(' ');chart=`<svg class="price-chart" viewBox="0 0 600 180" role="img" aria-label="روند حداقل قیمت ثبت‌شده؛ جدول ارقام در ادامه"><polyline points="${xy}" fill="none" stroke="#d73948" stroke-width="3"/></svg>`}box.innerHTML=`<p>${esc(d.notice)}</p>${d.baseline?`<p>آخرین ثبت فهرست: ${fa(d.baseline.price)} تومان · ${esc(formatDate(d.baseline.at,true))}</p>`:''}${chart}${points.length?'<div class="compare-table"><table><tr><th>زمان شمسی</th><th>قبلی</th><th>جدید (تومان)</th></tr>'+points.slice(-60).map(x=>`<tr><td>${esc(formatDate(x.at,true))}</td><td>${fa(x.previous)}</td><td>${fa(x.price)}</td></tr>`).join('')+'</table></div>':'<div class="empty">هنوز تغییر قیمتی در سامانه ثبت نشده است.</div>'}<h3>استعلام‌های ثبت‌شده توسط مدیر</h3>${d.observations.length?d.observations.slice(-20).reverse().map(o=>`<article class="market-record"><strong>${fa(o.price)} تومان · ${esc(shops[o.shop]?.name||o.shop)}</strong><p>${esc(formatDate(o.observedAt,true))} · ${esc(o.source)}</p><p>موجودی طبق استعلام: ${esc({unknown:'نامشخص',available:'موجود',unavailable:'ناموجود'}[o.stock])}</p></article>`).join(''):'<p>استعلام دارای منبع ثبت نشده است.</p>'}`}catch(e){box.textContent=e.message}}
 function report(p){modal(`<h2>گزارش مغایرت</h2><p>${esc(p.title)}</p><form id="reportForm"><label>موضوع<select id="reportKind"><option value="price">قیمت اشتباه</option><option value="stock">ناموجود بودن</option><option value="details">مشخصات محصول</option><option value="address">آدرس فروشگاه</option><option value="other">سایر</option></select></label><label>فروشگاه<select id="reportShop"><option value="">کل محصول</option>${[...new Set(p.offers.map(o=>o.shop))].map(id=>`<option value="${esc(id)}">${esc(shops[id]?.name||id)}</option>`).join('')}</select></label><label>توضیح<textarea id="reportText" minlength="5" maxlength="1000" required placeholder="چه موردی با اطلاعات صفحه مطابقت ندارد؟ اطلاعات شخصی ننویس."></textarea></label><button class="primary">ارسال گزارش</button><p id="reportResult" role="status"></p></form>`);$('#reportForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter,box=$('#reportResult');b.disabled=true;try{const d=await api('reports',{product:p.id,shop:$('#reportShop').value,kind:$('#reportKind').value,text:$('#reportText').value});storage.set('ty:reports',[...list('ty:reports'),{...d,title:p.title}].slice(-50));box.textContent='گزارش ثبت شد؛ پاسخ را از «گزارش‌های من» دنبال کن.';$('#reportText').value=''}catch(e){box.textContent=e.message;b.disabled=false}}}
 function watch(p){const old=list('ty:watches').find(w=>w.id===p.id);modal(`<h2>قیمت دلخواه من</h2><p>${esc(p.title)}</p><p>قیمت ثبت‌شده: ${fa(p.min)} تومان</p><form id="watchForm"><label>وقتی قیمت به این مقدار رسید<input id="targetPrice" inputmode="numeric" required value="${old?.target||''}" placeholder="تومان"></label><p class="small">بررسی هنگام باز کردن محصول انجام می‌شود؛ اعلان خارج از سایت ندارد.</p><button class="primary">ذخیرهٔ پیگیری</button></form>`);$('#watchForm').onsubmit=e=>{e.preventDefault();const target=parseAmount($('#targetPrice').value);if(!target||target>1e12)return toast('قیمت معتبر وارد کن.');storage.set('ty:watches',[...list('ty:watches').filter(w=>w.id!==p.id),{id:p.id,title:p.title,target,at:new Date().toISOString()}].slice(-50));$('#modal').close();toast('هدف قیمت ذخیره شد.')}}
 function attach(p){$('.detail-top .modal-actions').insertAdjacentHTML('beforeend','<button id="historyProduct">نمودار و سابقهٔ قیمت</button><button id="watchProduct">پیگیری قیمت</button><button id="reportProduct">گزارش مغایرت</button>');$('#historyProduct').onclick=()=>history(p);$('#watchProduct').onclick=()=>watch(p);$('#reportProduct').onclick=()=>report(p);const w=list('ty:watches').find(x=>x.id===p.id);if(w&&p.min>0&&p.min<=w.target)toast('قیمت ثبت‌شده به هدف تو رسیده است؛ قبل از خرید استعلام بگیر.')}
 return {attach};
}
